import sys
from math import comb
from functools import lru_cache

def solve():
    data = sys.stdin.read().split()
    N, P = int(data[0]), int(data[1])

    max_M = N*(N-1)//2
    min_M = N-1
    half = N // 2

    results_arr = [0] * (max_M + 1)

    def poly_mul(a, b):
        max_deg = max_M
        res = [0] * (max_deg + 1)
        for i in range(len(a)):
            if a[i] == 0:
                continue
            for j in range(len(b)):
                if i + j > max_deg:
                    break
                res[i+j] = (res[i+j] + a[i] * b[j]) % P
        return res

    def poly_pow(poly, exp):
        if exp == 0:
            res = [0] * (max_M + 1)
            res[0] = 1
            return res
        result = None
        base = list(poly)
        e = exp
        while e > 0:
            if e & 1:
                if result is None:
                    result = base[:]
                else:
                    result = poly_mul(result, base)
            base = poly_mul(base, base)
            e >>= 1
        return result

    @lru_cache(maxsize=None)
    def get_binom_poly(k):
        res = [0] * (max_M + 1)
        for i in range(min(k, max_M) + 1):
            res[i] = comb(k, i) % P
        return tuple(res)

    @lru_cache(maxsize=None)
    def get_transition_poly(a, b):
        bp = list(get_binom_poly(a))
        bp[0] = (bp[0] - 1) % P
        res = poly_pow(bp, b)
        return tuple(res)

    @lru_cache(maxsize=None)
    def get_within_poly(s):
        return get_binom_poly(s*(s-1)//2)

    def enumerate_sequences():
        sequences = []

        def rec(remaining, even_rem, odd_rem, depth, current):
            if remaining == 0:
                if even_rem == 0 and odd_rem == 0:
                    sequences.append(tuple(current))
                return

            is_odd_layer = (depth % 2 == 1)

            if is_odd_layer:
                max_s = min(remaining, odd_rem)
                for s in range(1, max_s + 1):
                    current.append(s)
                    rec(remaining - s, even_rem, odd_rem - s, depth + 1, current)
                    current.pop()
            else:
                max_s = min(remaining, even_rem)
                for s in range(1, max_s + 1):
                    current.append(s)
                    rec(remaining - s, even_rem - s, odd_rem, depth + 1, current)
                    current.pop()

        rec(N-1, half-1, half, 1, [])
        return sequences

    sequences = enumerate_sequences()

    # Precompute factorials for multinomial
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i-1] * i

    def multinomial(total, parts):
        res = fact[total]
        for p in parts:
            res //= fact[p]
        return res

    for seq in sequences:
        layers = [1] + list(seq)
        r = len(layers) - 1

        # Multinomial coefficient: (N-1)! / (s1! * ... * sr!)
        multi = multinomial(N-1, list(seq))
        multi_mod = multi % P

        if multi_mod == 0:
            continue

        # Compute GF = product of within-layer polys * product of transition polys
        gf = [0] * (max_M + 1)
        gf[0] = 1

        for i in range(len(layers)):
            s = layers[i]
            wp = get_within_poly(s)
            gf = poly_mul(gf, list(wp))

        for i in range(r):
            a = layers[i]
            b = layers[i+1]
            tp = get_transition_poly(a, b)
            gf = poly_mul(gf, list(tp))

        for m in range(min_M, max_M + 1):
            results_arr[m] = (results_arr[m] + multi_mod * gf[m]) % P

    print(' '.join(str(results_arr[m]) for m in range(min_M, max_M + 1)))

solve()
